with valid as (select id, customer_id, device, browser, started_at, country, lower(device) as device_lower, concat_ws('-', browser, device) as browser_device_key, coalesce(browser, 'N/A') as browser_clean from sessions where customer_id in (4, 22, 30, 33) and browser is not null) select s.* from valid s where not exists (select 1 from web_events c where c.session_id = s.id and c.event_time < s.started_at)
